using System;
using System.Text;
using Enterprise.DbUpgrader.Transformation.DataModification;
using Enterprise.DbUpgrader.Transformation.DataModification.Registry.Testing;
using Enterprise.DbUpgrader.Transformations.Transforms.MasterDataComplianceWise;
using NUnit.Framework;

namespace Enterprise.DbUpgrader.Transformations.Test.PostUpgrade.Public.MasterData.MasterDataComplianceWise
{
	[TestedType(typeof(CopyCommodityRiskCheckBypassFeatureToCommodityRiskAssessmentDecisionRegistryItem))]
	public class CopyCommodityRiskCheckBypassFeatureTrueToCommodityRiskAssessmentDecisionFalseRegistryItemTest : RegistryDataTransformationTestCase
	{
		DateTime transformationStartTime = DateTime.MaxValue;
		protected override void AssertTransformationResults()
		{
			const string registryName = "AllowComplianceCommodityRiskAssessment";
			AssertEquals(1, Helper.GetStmDataRowCount(registryName));
			var binaryValue = Helper.GetStmDataValue(registryName);
			var registryValue = Encoding.Unicode.GetString(binaryValue);
			AssertEquals("False", registryValue);

			var registryLog = Helper.AssertRegistryLogRecord(registryName, registryValue);
			AssertEquals("StmData", registryLog.Table);
			AssertEquals(registryValue, registryLog.Reference);
			AssertGreaterThan(registryLog.EventTime, transformationStartTime);
			AssertEquals("~BP", registryLog.User);
			AssertGreaterThan(registryLog.EventTimeUtc, transformationStartTime.ToUniversalTime());
		}

		protected override DataTransformation GetNewTestTransformationInstance() => new CopyCommodityRiskCheckBypassFeatureToCommodityRiskAssessmentDecisionRegistryItem();

		protected override void PrepareTestData()
		{
			transformationStartTime = DateTime.Now;
			const string encodedEncryptedCompressedFeatureControlRuleContent = "";
			Helper.InsertStmDataRow("FeatureControlRuleContent", "STR", Encoding.Unicode.GetBytes(encodedEncryptedCompressedFeatureControlRuleContent));
		}
	}
}
